      { heroId: 220, tag: "HAY", team: 2, x: 23 - 3 * Math.cos(t * 0.6), z: -21 - 3 * Math.sin(t * 0.6), hp: 3800 + Math.cos(t) * 500, maxHp: 4500 },
      { heroId: 225, tag: "THA", team: 2, x: 21 - 2.5 * Math.cos(t * 0.6), z: -19 - 2.5 * Math.sin(t * 0.6), hp: 7600 + Math.sin(t) * 800, maxHp: 8900 }
